#!/bin/sh
# Generated by FWShift: an AWS Network Firewall policy and its stateful rule group, created with the AWS CLI. Read the
# report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE    prints the calls, makes none (no AWS access needed)
#   CHECK=1 sh THIS_FILE      sends every call with --dry-run: AWS checks the requests and the permissions
#   sh THIS_FILE              creates the rule group and the policy
#
# AWS_OPTS adds options to every call, for example AWS_OPTS='--region eu-west-1 --profile prod'.
#
# The policy is attached to no firewall: nothing changes for any traffic until you associate it:
#   aws network-firewall associate-firewall-policy --firewall-name FIREWALL --firewall-policy-arn ARN
# A rule group or policy of the same name stops the script before anything is created; a call AWS refuses stops it
# where it is (delete what it made with aws network-firewall delete-rule-group / delete-firewall-policy and run it
# again).
set -u
DRY_RUN="${DRY_RUN:-}"
CHECK="${CHECK:-}"
AWS_OPTS="${AWS_OPTS:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
show() { printf 'aws network-firewall' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; }
TMP=$(mktemp -d) || fail "mktemp"
trap 'rm -rf "$TMP"' EXIT
# free_group NAME / free_policy NAME: stop the script when one of that name exists
free_group() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-rule-group --rule-group-name "$1" --type STATEFUL $AWS_OPTS >/dev/null 2>&1; then
    fail "a rule group named $1 exists already; nothing was created"
  fi
}
free_policy() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-firewall-policy --firewall-policy-name "$1" $AWS_OPTS >/dev/null 2>&1; then
    fail "a firewall policy named $1 exists already; nothing was created"
  fi
}
# group NAME CAPACITY FILE: creates a stateful rule group and prints its ARN
group() {
  if [ -n "$DRY_RUN" ]; then
    show create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3"
    printf 'arn:aws:network-firewall:dryrun:000000000000:stateful-rulegroup/%s\n' "$1"
    return 0
  fi
  if [ -n "$CHECK" ]; then
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --dry-run --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1 (dry run)"
    printf 'checked: rule group %s\n' "$1" >&2
  else
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --description 'Generated by FWShift' --tags Key=fwshift,Value=generated \
      --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1"
    printf 'created %s\n' "$arn" >&2
  fi
  printf '%s\n' "$arn"
}
# policy NAME FILE CHECKFILE: creates the firewall policy (with CHECK, checks it without its rule groups, which a dry run
# does not create)
policy() {
  if [ -n "$DRY_RUN" ]; then show create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2"; return 0; fi
  if [ -n "$CHECK" ]; then
    aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$3" --dry-run $AWS_OPTS >/dev/null \
      || fail "create-firewall-policy $1 (dry run)"
    printf 'checked: firewall policy %s\n' "$1" >&2
    return 0
  fi
  aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2" \
    --description 'Generated by FWShift; review the conversion report before associating it' \
    --tags Key=fwshift,Value=generated $AWS_OPTS >/dev/null || fail "create-firewall-policy $1"
  printf 'created firewall policy %s\n' "$1" >&2
}

# No rule group or policy of these names may exist.
free_group fwshift-rules
free_policy fwshift

# Rule group 1: 35 rules, in the order of the policy.
cat > "$TMP/group1.json" <<'FWSHIFT_JSON'
{
 "RuleVariables": {
  "IPSets": {
   "ADMIN_NETS": {
    "Definition": [
     "10.30.10.0/24"
    ]
   },
   "FWS_HOME_NET": {
    "Definition": [
     "10.20.0.0/16",
     "2001:db8:20::/56"
    ]
   },
   "WEB_SERVERS": {
    "Definition": [
     "10.20.1.0/24",
     "2001:db8:20:1::/64"
    ]
   },
   "partners": {
    "Definition": [
     "198.51.100.128/25",
     "203.0.113.0/26"
    ]
   }
  }
 },
 "RulesSource": {
  "RulesString": "pass ip any any -> any any (msg:\"fwshift-replies\"; flow:to_client; sid:35; rev:1;)\ndrop tcp 0.0.0.0/0 22 -> 198.51.100.0/24 any (msg:\"sl-edge-1-replies\"; flow:to_server; sid:1; rev:1;)\ndrop ip ::/0 any -> 2001:db8:bad::/48 any (msg:\"sl-edge-20-replies\"; flow:to_server; ip_proto:!58; sid:2; rev:1;)\ndrop icmp ::/0 any -> 2001:db8:bad::/48 any (msg:\"sl-edge-20-replies-2\"; flow:to_server; ip_proto:58; itype:128; sid:3; rev:1;)\ndrop tcp 198.51.100.0/24 any -> 0.0.0.0/0 22 (msg:\"sl-edge-1\"; flow:to_server; sid:4; rev:1;)\npass tcp 10.20.8.0/24 any -> 10.40.0.0/24 873 (msg:\"sl-edge-5\"; flow:to_server; sid:5; rev:1;)\npass tcp 10.40.0.0/24 873 -> 10.20.8.0/24 any (msg:\"sl-edge-6\"; flow:to_server; sid:6; rev:1;)\ndrop ip 2001:db8:bad::/48 any -> ::/0 any (msg:\"sl-edge-20\"; flow:to_server; sid:7; rev:1;)\npass tcp $FWS_HOME_NET any -> any 443 (msg:\"sf-baseline-100\"; flow:to_server; sid:8; rev:1;)\npass tcp $FWS_HOME_NET any -> any 80 (msg:\"sf-baseline-101\"; flow:to_server; sid:9; rev:1;)\ndrop tcp any any -> 10.20.5.0/24 22 (msg:\"sf-baseline-102\"; flow:to_server; sid:10; rev:1;)\ndrop tcp 10.20.5.0/24 22 -> any any (msg:\"sf-baseline-102-rev\"; flow:to_server; sid:11; rev:1;)\nreject tcp any any -> 10.20.6.10/32 3389 (msg:\"sf-baseline-103\"; flow:to_server; sid:12; rev:1;)\npass icmp $FWS_HOME_NET any -> any any (msg:\"sf-baseline-105\"; flow:to_server; ip_proto:1; itype:8; sid:13; rev:1;)\npass icmp $FWS_HOME_NET any -> any any (msg:\"sf-baseline-105\"; flow:to_server; ip_proto:58; itype:8; sid:14; rev:1;)\npass udp 2001:db8:20::/56 any -> 2001:db8:ff::53/128 53 (msg:\"sf-baseline-106\"; flow:to_server; sid:15; rev:1;)\npass tcp 10.30.0.0/16 1024:65535 -> 10.20.4.0/24 [5432,6432] (msg:\"sf-baseline-107\"; flow:to_server; sid:16; rev:1;)\npass tcp any any -> $WEB_SERVERS [80,443,8443] (msg:\"sf-app-1000\"; flow:to_server; sid:17; rev:1;)\npass tcp $FWS_HOME_NET any -> any 53 (msg:\"sf-app-1003\"; flow:to_server; sid:18; rev:1;)\npass udp $FWS_HOME_NET any -> any 53 (msg:\"sf-app-1003\"; flow:to_server; sid:19; rev:1;)\ndrop tcp $partners any -> $FWS_HOME_NET [1:21,23:1023] (msg:\"sf-app-1004\"; flow:to_server; sid:20; rev:1;)\npass ip 10.20.7.0/24 any -> any any (msg:\"sf-app-1007\"; flow:to_server; ip_proto:47; sid:21; rev:1;)\ndrop udp any any -> 10.20.2.0/24 161 (msg:\"sf-app-1011\"; flow:to_server; sid:22; rev:1;)\npass tcp [10.30.0.0/18,10.30.64.0/19,10.30.96.0/23,10.30.98.0/24,10.30.100.0/22,10.30.104.0/21,10.30.112.0/20,10.30.128.0/17] any -> 10.20.3.0/24 1024:65535 (msg:\"sf-app-1012\"; flow:to_server; sid:23; rev:1;)\ndrop ip !$FWS_HOME_NET any -> $FWS_HOME_NET any (msg:\"sf-app-1013\"; flow:to_server; sid:24; rev:1;)\ndrop ip any any -> any any (msg:\"stateful-default-not-tcp\"; flow:to_server; ip_proto:!6; sid:25; rev:1;)\npass tcp any 443 -> $FWS_HOME_NET any (msg:\"sf-baseline-100-reply\"; flow:to_server; sid:26; rev:1;)\nreject tcp 10.20.6.10/32 3389 -> any any (msg:\"sf-baseline-103-reply\"; flow:to_server; sid:27; rev:1;)\npass tcp any any -> $FWS_HOME_NET 53 (msg:\"sf-app-1003-reply\"; flow:to_server; sid:28; rev:1;)\npass udp any any -> $FWS_HOME_NET 53 (msg:\"sf-app-1003-reply\"; flow:to_server; sid:29; rev:1;)\npass tcp any any -> $FWS_HOME_NET any (msg:\"sf-app-1009-reply\"; flow:to_server; sid:30; rev:1;)\npass tcp $ADMIN_NETS any -> $WEB_SERVERS 22 (msg:\"sf-app-1001\"; flow:to_server; sid:31; rev:1;)\npass tcp $FWS_HOME_NET any -> !$FWS_HOME_NET 443 (msg:\"sf-app-1002\"; flow:to_server; sid:32; rev:1;)\ndrop tcp $FWS_HOME_NET any -> !$FWS_HOME_NET 443 (msg:\"dl-egress-2\"; flow:to_server; sid:33; rev:1;)\ndrop tcp $FWS_HOME_NET any -> !$FWS_HOME_NET 80 (msg:\"dl-egress-4\"; flow:to_server; sid:34; rev:1;)\n"
 },
 "StatefulRuleOptions": {
  "RuleOrder": "STRICT_ORDER"
 }
}
FWSHIFT_JSON
G1=$(group fwshift-rules 100 "$TMP/group1.json") || exit 1

# The policy: every packet to the stateful engine, the rule groups in strict order, then the default of the source.
cat > "$TMP/policy.json" <<FWSHIFT_JSON
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"},"StatefulRuleGroupReferences":[{"ResourceArn":"${G1}","Priority":100}]}
FWSHIFT_JSON
cat > "$TMP/policy-check.json" <<'FWSHIFT_JSON'
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"}}
FWSHIFT_JSON
policy fwshift "$TMP/policy.json" "$TMP/policy-check.json"

# Not written:
#   sl-edge-12: not converted: TCP flags: the rule matches some packets of a connection and not others
#   ThreatSignaturesMalwareStrictOrder-1: not converted: rule group ThreatSignaturesMalwareStrictOrder is not in the input; add the answer of describe-rule-group for arn:aws:network-firewall:eu-west-1:aws-managed:stateful-rulegroup/ThreatSignaturesMalwareStrictOrder (an AWS managed rule group, whose rules AWS may not show)
#   sf-app-1005: references 'branches': the entries of prefix list pl-0f9e8d7c6b5a40321 are not in the input (add the answer of aws ec2 get-managed-prefix-list-entries, wrapped with its PrefixListId)
#   sf-app-1005-rev: references 'branches': the entries of prefix list pl-0f9e8d7c6b5a40321 are not in the input (add the answer of aws ec2 get-managed-prefix-list-entries, wrapped with its PrefixListId)
#   sf-app-1008: disabled in the source
#   sf-app-1006: not converted: keyword http.uri; not converted: keyword content:"/admin"
#   dl-block-1: not converted: tls.sni: the rule matches by domain name, which is not an address
#   dl-egress-1: not converted: tls.sni: the rule matches by domain name, which is not an address
#   dl-egress-3: not converted: http.host: the rule matches by domain name, which is not an address
#   sf-app-1010: disabled in the source

echo 'Done. Associate the policy with a firewall when you are ready; until then nothing changes.' >&2
